//! Console demonstration of an owner-led Pareto comparison.
//!
//! Run from the workspace root:
//!   cargo run -p symtropy-bevy-scene --example owner_led_home_alternatives
//!
//! These are synthetic ratings supplied by an imaginary household. They are not
//! measurements, architecture generated by the system, or compliance results.

use symtropy_bevy_scene::{
    AlternativeDisposition, DesignAlternative, DesignComparison, DesignIntent, DesignIntentClass,
    IntentEvaluation, IntentEvaluationOutcome, IntentOrigin, IntentPriority,
    PreferencePairRelation, compute_owner_preference_frontier,
};

fn intent(id: &str, class: DesignIntentClass) -> DesignIntent {
    DesignIntent {
        intent_id: id.into(),
        title: id.into(),
        description: "Synthetic homeowner design intent".into(),
        class,
        priority: IntentPriority::Important,
        origin: if class == DesignIntentClass::BindingRequirement {
            IntentOrigin::JurisdictionRulePack
        } else {
            IntentOrigin::OwnerBrief
        },
        source_ref: (class == DesignIntentClass::BindingRequirement)
            .then(|| "source:synthetic-egress-clause".into()),
        source_module_id: (class == DesignIntentClass::BindingRequirement)
            .then(|| "module:synthetic-jurisdiction-r1".into()),
        decision_owner_id: None,
        uncertainty_note: None,
    }
}

fn evaluation(id: &str, outcome: IntentEvaluationOutcome) -> IntentEvaluation {
    IntentEvaluation {
        intent_id: id.into(),
        outcome,
        explanation: "Synthetic example input; not a verified technical finding".into(),
        evidence_ref: (outcome == IntentEvaluationOutcome::Satisfied)
            .then(|| format!("synthetic-evidence:{id}")),
        not_applicable_rationale: None,
        uncertainty_note: None,
        preference_rating: None,
    }
}

fn rated_preference(id: &str, rating: u8) -> IntentEvaluation {
    let mut item = evaluation(id, IntentEvaluationOutcome::Satisfied);
    item.preference_rating = Some(rating);
    item
}

fn alternative(
    id: &str,
    title: &str,
    disposition: AlternativeDisposition,
    evaluations: Vec<IntentEvaluation>,
) -> DesignAlternative {
    DesignAlternative {
        candidate_id: id.into(),
        design_revision_id: format!("{id}:revision-1"),
        title: title.into(),
        disposition,
        decision_owner_id: None,
        disposition_rationale: "Retained for household comparison".into(),
        evaluations,
    }
}

fn main() {
    let comparison = DesignComparison {
        comparison_id: "demo:home-comparison-1".into(),
        owner_brief_revision_id: "demo:owner-brief-1".into(),
        intents: vec![
            intent("rule:egress", DesignIntentClass::BindingRequirement),
            intent("owner:daylight", DesignIntentClass::OwnerPreference),
            intent("owner:privacy", DesignIntentClass::OwnerPreference),
        ],
        alternatives: vec![
            alternative(
                "garden",
                "Garden-facing, daylight-forward home",
                AlternativeDisposition::ReadyForTechnicalAssessment,
                vec![
                    evaluation("rule:egress", IntentEvaluationOutcome::Satisfied),
                    rated_preference("owner:daylight", 92),
                    rated_preference("owner:privacy", 38),
                ],
            ),
            alternative(
                "courtyard",
                "Private courtyard home",
                AlternativeDisposition::ReadyForTechnicalAssessment,
                vec![
                    evaluation("rule:egress", IntentEvaluationOutcome::Satisfied),
                    rated_preference("owner:daylight", 58),
                    rated_preference("owner:privacy", 91),
                ],
            ),
            alternative(
                "compact",
                "Compact, lower-complexity home",
                AlternativeDisposition::ReadyForTechnicalAssessment,
                vec![
                    evaluation("rule:egress", IntentEvaluationOutcome::Satisfied),
                    rated_preference("owner:daylight", 43),
                    rated_preference("owner:privacy", 44),
                ],
            ),
            alternative(
                "regional",
                "Regional-vernacular interpretation",
                AlternativeDisposition::OpenForExploration,
                vec![
                    evaluation("rule:egress", IntentEvaluationOutcome::Satisfied),
                    rated_preference("owner:daylight", 73),
                    evaluation("owner:privacy", IntentEvaluationOutcome::Unknown),
                ],
            ),
        ],
    };

    let report = match compute_owner_preference_frontier(&comparison) {
        Ok(report) => report,
        Err(issues) => {
            eprintln!("Invalid comparison contract: {issues:#?}");
            std::process::exit(1);
        }
    };

    println!("Owner-led design comparison (synthetic demo)");
    println!("Owner preferences are subjective input, not objective measurements.");
    println!("No scalar 'happiness score' is computed.");
    println!("Candidates retained on the Pareto frontier:");
    for id in &report.frontier_candidate_ids {
        if let Some(candidate) = comparison
            .alternatives
            .iter()
            .find(|item| &item.candidate_id == id)
        {
            println!("  - {} ({})", candidate.title, candidate.candidate_id);
        }
    }
    println!("Candidates dominated on all comparable rated dimensions:");
    for id in &report.dominated_candidate_ids {
        if let Some(candidate) = comparison
            .alternatives
            .iter()
            .find(|item| &item.candidate_id == id)
        {
            println!("  - {} ({})", candidate.title, candidate.candidate_id);
        }
    }
    println!("Pairwise trade-offs and unknowns:");
    for pair in &report.pairwise_comparisons {
        if matches!(
            pair.relation,
            PreferencePairRelation::Tradeoff
                | PreferencePairRelation::IncomparableMissingRatings
                | PreferencePairRelation::NotComparable
        ) {
            println!(
                "  - {} vs {}: {:?}; left better on {:?}; right better on {:?}; missing {:?}",
                pair.left_candidate_id,
                pair.right_candidate_id,
                pair.relation,
                pair.left_better_on,
                pair.right_better_on,
                pair.missing_ratings_on
            );
        }
    }
    println!(
        "Hard-rule and engineering truth are outside the preference ranking; this demo does not establish compliance or buildability."
    );
}
